function permute(nums: number[]): number[][] {
  const result: number[][] = [];
  const path: number[] = [];
  // used[i] — стоит ли nums[i] уже в текущей перестановке
  const used: boolean[] = new Array(nums.length).fill(false);

  const backtrack = (): void => {
    // Использовали все числа — перестановка готова
    if (path.length === nums.length) {
      result.push([...path]);
      return;
    }

    // На каждую позицию пробуем любое ещё не использованное число
    for (let i = 0; i < nums.length; i++) {
      if (used[i]) continue;
      used[i] = true;
      path.push(nums[i]); // выбор
      backtrack();
      path.pop(); // откат
      used[i] = false;
    }
  };

  backtrack();
  return result;
}

// Время: O(n · n!) — n! перестановок, каждая копируется за O(n)
// Память: O(n) на рекурсию, путь и used (без учёта ответа)

